#include <cstdio>
#include <queue>
using namespace std;

struct Node {
    int r, c, time;
};

char grid[8][9];
bool visited[8][8][25];

bool hasStatue(int r, int c, int time) {
    if (time < 0) return false;
    int originalRow = r - time / 2;
    return originalRow >= 0 && originalRow < 8 &&
           grid[originalRow][c] == 'S';
}

int main() {
    for (int i = 0; i < 8; ++i)
        scanf("%8s", grid[i]);

    queue<Node> q;
    q.push({7, 0, -1});
    visited[7][0][0] = true;

    while (!q.empty()) {
        Node cur = q.front();
        q.pop();

        if (hasStatue(cur.r, cur.c, cur.time) ||
            hasStatue(cur.r, cur.c, cur.time + 1))
            continue;

        if (cur.r == 0 && cur.c == 7) {
            printf("WIN\n");
            return 0;
        }

        for (int dr = -1; dr <= 1; ++dr) {
            for (int dc = -1; dc <= 1; ++dc) {
                int nr = cur.r + dr;
                int nc = cur.c + dc;

                if (nr < 0 || nr >= 8 || nc < 0 || nc >= 8)
                    continue;

                for (int dt = 1; dt <= 2; ++dt) {
                    int nt = cur.time + dt;
                    if (nt >= 24 || visited[nr][nc][nt + 1])
                        continue;

                    visited[nr][nc][nt + 1] = true;
                    q.push({nr, nc, nt});
                }
            }
        }
    }

    printf("LOSE\n");
    return 0;
}

