            for (int dc = -1; dc <= 1; ++dc) {
                int nr = cur.r + dr;
                int nc = cur.c + dc;

                if (nr < 0 || nr >= 8 || nc < 0 || nc >= 8)
                    continue;

                q.push({nr, nc, cur.time < 15 ? cur.time + 1 : 16});
                q.push({nr, nc, cur.time < 14 ? cur.time + 2 : 16});
