bool visited[9][8][8];

bool blocked(int r, int c, int time) {
    int originalRow = r - time;
    return originalRow >= 0 && grid[originalRow][c] == 'S';
}

int main() {
    for (int i = 0; i < 8; ++i)
        scanf("%8s", grid[i]);

    queue<Node> q;
    q.push({7, 0, 0});
    visited[0][7][0] = true;

    while (!q.empty()) {
        Node cur = q.front();
        q.pop();

        if (blocked(cur.r, cur.c, cur.time))
            continue;

        if ((cur.r == 0 && cur.c == 7) || cur.time >= 8) {
            printf("WIN\n");
            return 0;
        }

        int nextTime = cur.time + 1;

        for (int dr = -1; dr <= 1; ++dr) {
            for (int dc = -1; dc <= 1; ++dc) {
                int nr = cur.r + dr;
                int nc = cur.c + dc;

                if (nr < 0 || nr >= 8 || nc < 0 || nc >= 8)
                    continue;
                if (blocked(nr, nc, cur.time) ||
                    blocked(nr, nc, nextTime))
                    continue;

                int storedTime = nextTime > 8 ? 8 : nextTime;
                if (!visited[storedTime][nr][nc]) {
                    visited[storedTime][nr][nc] = true;
                    q.push({nr, nc, storedTime});
                }
            }
        }
    }

    printf("LOSE\n");
    return 0;
}

